internal val infectionsDHConditions: List<Condition> = listOf(
    Condition(
        id = "inf-dengue", title = "Dengue fever",
        summary = "Acute Aedes-borne flavivirus (DENV-1–4) febrile illness that can progress around defervescence (days 3–7) to capillary plasma leakage, shock, severe bleeding, or organ failure; managed with phase- and haematocrit-guided isotonic fluids.",
        keywords = listOf("dengue", "DENV", "breakbone fever", "DHF", "DSS", "dengue shock syndrome", "NS1", "thrombocytopenia", "plasma leakage", "Aedes aegypti", "tourniquet test", "A90"),
        population = Population.Infections,
        image = ConditionImage("inf_dengue_rash", "Confluent erythematous convalescent dengue rash demonstrating the classic \"white islands in a sea of red\" sparing pattern seen during the recovery phase.", "Ranjan Premaratna. Professor in medicine. Department of medicine. University of kelaniya. Sri Lanka.", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Dengue_recovery_rash_(White_islands_in_red_sea).jpg"),
        firstSteps = listOf(
            "Triage by exact day of fever onset and clinical group (A, B, or C): assess oral fluid tolerance, urine output, high-risk comorbidities (pregnancy, infancy, age >65 y, obesity, diabetes, CKD/CLD/CAD), and check for warning signs or shock.",
            "Assess haemodynamics immediately: pulse volume, BP, pulse pressure (narrow if <20 mmHg), capillary refill time (CRT >2 s), extremity warmth, postural hypotension (SBP drop ≥20 mmHg or DBP drop ≥10 mmHg), and tourniquet test.",
            "Order baseline CBC (Hb, Hct/PCV, TLC, platelets) and day-appropriate dengue assay; never delay fluid therapy awaiting lab confirmation.",
            "Give paracetamol + oral fluids (ORS/coconut water) for Group A, admit Groups B/C for monitored isotonic IV crystalloids, and notify the District Vector Borne Disease (VBD) Officer.",
        ),
        info = listOf(
            InfoBlock("Investigation of choice (IOC)", listOf(
                "Days 1–5 of fever (India NCVBDC primary rule) — IOC: NS1 antigen by ELISA (or RT-PCR/NAAT in acute-phase serum).",
                "After Day 5 (>5 days of fever) — IOC: Dengue IgM by MAC-ELISA (CDC 2025 recommends NAAT or NS1 ELISA + IgM during days 0–7, and IgM alone >7 days).",
                "Rapid Diagnostic Tests (RDTs) are not recommended by NCVBDC for diagnosis or clinical decisions (positive RDT = \"probable\" dengue only); single-sample IgG-ELISA reflects past infection only.",
            ), listOf(cite("inf-dh-ncvbdc-dengue-2023"), cite("inf-dh-icmr-stw-dengue-2019"), cite("inf-dh-cdc-dengue-test-2025"))),
            InfoBlock("Other Investigations & Key Findings", listOf(
                "Serial Haematocrit (Hct/PCV) & Platelets: check daily in Group A (fever >3 d), every 4–6 h in admitted patients, and before/after (never during) each fluid bolus in shock. A ≥10% Hct rise above baseline signals plasma leakage (≥20% in moderate/severe dengue); rising Hct with rapidly falling platelets heralds the critical phase.",
                "Tourniquet test: inflate cuff midway between SBP and DBP for 5 min; positive = ≥10 petechiae per 2.5 cm² (>20 in severe dengue; may be negative in profound shock).",
                "Moderate/severe workup: RBS, ABG + lactate, electrolytes (Na+, K+, Ca2+), RFT, LFT (AST/ALT ≥1,000 U/L = severe organ involvement), PT/aPTT/fibrinogen, blood grouping/crossmatch, CXR/USG (pleural effusion, ascites, IVC collapsibility), and screen for endemic co-infections (malaria, scrub typhus, leptospirosis, typhoid, chikungunya).",
            ), listOf(cite("inf-dh-ncvbdc-dengue-2023"), cite("inf-dh-icmr-stw-dengue-2019"))),
        ),
        tiers = listOf(
            Tier("Group A (Outpatient — no warning signs) & Group B (Inpatient — warning signs / high-risk)", "No specific antiviral exists; careful isotonic fluid titration guided by Hct and urine output (~0.5 mL/kg/h) is life-saving. Calculate fluid volumes using Ideal Body Weight (IBW) in overweight/obese patients (NCVBDC 2023).", listOf(
                Drug("Paracetamol (Group A & inpatient antipyretic)", "Adults: 500–1000 mg PO q6h (max 4 g/day); Children: 10–15 mg/kg/dose PO q6h", maxDose = "4 g/day in adults", weightDose = WeightDose(10.0, 15.0, "mg", "per dose PO every 6 h"), cautions = listOf("Pair with oral hydration (ORS, coconut water) and tepid sponging; daily CBC/Hct review in Group A."), citations = listOf(cite("inf-dh-ncvbdc-dengue-2023"), cite("inf-dh-cdc-dengue-care-2026"))),
                Drug("Isotonic Crystalloid — 0.9% NaCl or Ringer's Lactate (Group B inpatient)", "Start 7–10 mL/kg over 1 h (children: 5–10 mL/kg/h); if improving, taper 5–7 mL/kg/h (2–4 h) → 3–5 mL/kg/h (2–4 h) → 2–4 mL/kg/h (2–4 h); stop IV fluids at 24–48 h", cautions = listOf("If no improvement after 1st bolus and Hct >45%, give 2nd bolus 10 mL/kg over 1 h (if still unimproved → Group C). If Hct <45% with worsening status, suspect occult bleeding → whole blood 10 mL/kg or PRBC 5 mL/kg. Infants <6 mo may use 0.45% NaCl during critical phase."), citations = listOf(cite("inf-dh-ncvbdc-dengue-2023"), cite("inf-dh-icmr-stw-dengue-2019"))),
            )),
            Tier("Group C — Severe Dengue (Shock, Severe Bleeding, & Special Groups)", null, listOf(
                Drug("Isotonic Crystalloid / Colloid Resuscitation (Compensated & Hypotensive Shock)", "Compensated shock: 0.9% NS or RL 10–20 mL/kg over 1 h, then taper (7–10 → 5–7 → 3–5 → 2–3 mL/kg/h up to 24–48 h). Decompensated/hypotensive shock: 20 mL/kg over 15 min (max 500 mL/bolus; up to 3 rapid boluses if Hct >45%); if refractory leakage, hyper-oncotic colloid e.g. Dextran 40 10 mL/kg bolus (max 30 mL/kg/day)", cautions = listOf("Correct ABCS (Acidosis, Bleeding, Ca/Na/K, Sugar); start vasopressors/inotropes (noradrenaline/adrenaline/dopamine) for refractory hypotension. Stop IV fluids once out of critical phase (>24–48 h afebrile); for frank pulmonary oedema give furosemide 1 mg/kg IV (children 0.1–0.5 mg/kg/dose)."), citations = listOf(cite("inf-dh-ncvbdc-dengue-2023"), cite("inf-dh-icmr-stw-dengue-2019"))),
                Drug("Blood Products (Severe Bleeding / Falling Hct ONLY)", "Fresh whole blood 10 mL/kg OR PRBC 5 mL/kg (children with persistent shock + falling Hct: 20 mL/kg). Platelets ONLY if active bleeding (or prophylactic ONLY if <10,000/mm³ without bleeding): 5–6 units RDP or 1 unit SDP (adults); 10–15 mL/kg (infants)", cautions = listOf("Pregnancy: admit all symptomatic pregnant patients (high pulmonary oedema/bleeding risk). CAD: hold aspirin/antiplatelets if platelets <1,00,000/mm³ or with bleeding/leakage."), citations = listOf(cite("inf-dh-ncvbdc-dengue-2023"), cite("inf-dh-icmr-stw-dengue-2019"))),
            )),
        ),
        avoid = listOf(
            Caution("Aspirin and NSAIDs (ibuprofen, diclofenac)", "Markedly increase mucosal and GI bleeding risk.", listOf(cite("inf-dh-ncvbdc-dengue-2023"), cite("inf-dh-cdc-dengue-care-2026"))),
            Caution("Routine corticosteroids", "No therapeutic benefit in dengue (reserved only for specific indications such as raised ICP in hepatic encephalopathy or HLH).", listOf(cite("inf-dh-ncvbdc-dengue-2023"), cite("inf-dh-cdc-dengue-care-2026"))),
            Caution("Routine prophylactic platelet transfusion", "Platelet count poorly predicts bleeding; transfusing above 10,000/mm³ without bleeding causes harm without preventing haemorrhage.", listOf(cite("inf-dh-ncvbdc-dengue-2023"), cite("inf-dh-cdc-dengue-care-2026"))),
            Caution("IM injections, unnecessary invasive tapping, hypotonic IV fluids (>6 mo), or continuing IV fluids >48 h past critical phase", "Risk of fatal haemorrhage, hyponatraemia, or pulmonary oedema.", listOf(cite("inf-dh-ncvbdc-dengue-2023"))),
        ),
        escalate = listOf(
            "Warning signs (admit immediately): persistent vomiting (≥3/h or ≥4 in 6 h), severe abdominal pain, clinical fluid accumulation (ascites/pleural effusion), mucosal bleeding, lethargy/restlessness, hepatomegaly >2 cm, progressive Hct rise with rapid platelet drop.",
            "Severe dengue / ICU: narrow pulse pressure (<20 mmHg), hypotension, CRT >2 s, oliguria (<0.5 mL/kg/h), SpO2 <90%, GCS <9 or seizures, AST/ALT ≥1,000 U/L, severe bleeding, myocarditis, or AKI.",
        ),
        citations = listOf(cite("inf-dh-ncvbdc-dengue-2023"), cite("inf-dh-cdc-dengue-care-2026"), cite("inf-dh-cdc-dengue-test-2025"), cite("inf-dh-icmr-stw-dengue-2019")),
