        keywords = listOf("diphtheria", "Corynebacterium diphtheriae", "pseudomembrane", "bull neck", "DAT", "diphtheria antitoxin", "Elek test", "stridor", "myocarditis", "A36"),
        population = Population.Infections,
        image = ConditionImage("inf_diphtheria_bull_neck", "Child with severe respiratory diphtheria showing marked diffuse cervical lymphadenopathy and soft-tissue oedema (\"bull neck\"), an indication for high-dose (80,000 IU) diphtheria antitoxin and urgent airway vigilance.", "CDC", "Public domain", "https://commons.wikimedia.org/wiki/File:Diphtheria_bull_neck.5325_lores.jpg"),
        firstSteps = listOf(
            "Isolate immediately with droplet + contact precautions (separate ventilated area, ≥1 m spacing, mask/N95 for airway procedures, eye protection, gown, gloves).",
            "Assess airway gently without agitating the patient (stridor, tachypnoea, chest indrawing, drooling, restlessness, SpO2 <90%); alert ENT/anaesthesia immediately if compromised.",
            "Gently collect 2 swabs (throat from edge/beneath membrane + nasopharyngeal) before antibiotics if feasible without delaying therapy.",
            "Administer Diphtheria Antitoxin (DAT) and first-line macrolide antibiotic immediately on clinical suspicion — never wait for culture/Elek results; notify IDSP for contact tracing.",
